-- Сгенерировано build/stages/make_71_catalog.py — правьте генератор, а не этот файл.
-- Каталог для ORDA: страны американских образцов, реальные образцы ВС РК, ТТХ. Идемпотентно.
BEGIN;

UPDATE mil_core.item SET country = 'США' WHERE item_sname IN ('120-мм выстрелы к M256 (БК)', '25-мм выстрелы к M242 (БК)', '9-мм M17', 'M1283 AMPV GP', 'ПТРК FGM-148 Javelin');


DELETE FROM mil_core.item_spec WHERE note = 'этап 71';


DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM mil_core.item i WHERE coalesce(i.country, '') <> 'США'
             AND NOT EXISTS (SELECT 1 FROM mil_core.item_spec s WHERE s.item_sname = i.item_sname)) THEN
    RAISE EXCEPTION 'остались образцы (кроме США) без ТТХ: %',
      (SELECT string_agg(item_sname, ', ') FROM mil_core.item i WHERE coalesce(i.country, '') <> 'США'
       AND NOT EXISTS (SELECT 1 FROM mil_core.item_spec s WHERE s.item_sname = i.item_sname));
  END IF;
END $$;
COMMIT;

